 async Task RestoreKey(){string f=Path.Combine(dataRoot,".poker-data","ai-settings.json");if(!File.Exists(f))return;try{string cipher=J.Parse(File.ReadAllText(f))["encryptedKey"].S;if(cipher.StartsWith("dpapi:")){string key=Encoding.UTF8.GetString(ProtectedData.Unprotect(Convert.FromBase64String(cipher.Substring(6)),null,DataProtectionScope.CurrentUser));await rules.Call("key-init",J.O("key",key));}}catch{Notice("当前 Windows 账户无法解密已保存的 Key，请在设置中重新填写。");}}
