 async Task<bool> Run(string command,object data=null,bool repaint=true,bool interrupt=false){if(endingTable&&command!="end")return false;if(busy&&!interrupt)return false;int revision=++stateRevision;if(!interrupt)busy=true;try{J next=await rules.Call(command,data);if(revision!=stateRevision)return true;if(!next["app"].Null){bool wasSeated=!Session.Null;state=next;if(Session.Null){fastFold=false;straddleNext=false;paused=false;}if(repaint)Render();if(wasSeated&&Session.Null){HideOverlay();if(!repaint)Render();ShowSummary();}}Notice(!next["message"].Null?next["message"].S:"进度已自动保存");return true;}catch(Exception ex){if(revision==stateRevision){Notice(ex.Message);if(command!="tick")ShowGameMessage("操作未完成",ex.Message);}return false;}finally{if(!interrupt)busy=false;}}
