 async Task Pulse(){if(closing||endingTable||state.Null)return;UpdateClocks();if(busy||paused||dialogCount>0)return;if(Session.Null){if((DateTime.UtcNow-lastPoll).TotalMinutes>=1){lastPoll=DateTime.UtcNow;await Run("state",null,false);}return;}
  if(Hand["status"].S=="complete"){if(settleAt==DateTime.MaxValue)settleAt=DateTime.UtcNow.AddSeconds(5);if(!reviewHold&&DateTime.UtcNow>=settleAt){await NextHand();}return;}
  if(DateTime.UtcNow<bufferUntil)return;
  if(!Hand["actor"].Null&&Hand["actor"].I==0){if(fastFold&&Hand["street"].S=="preflop"){await Act("fold");return;}double deadline=Hand["actionDeadlineAt"].N;if(deadline>0&&DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()>=deadline)await Run("timeout",Turn());return;}
  if((DateTime.UtcNow-lastPoll).TotalMilliseconds<500)return;lastPoll=DateTime.UtcNow;int count=Hand["eventCount"].I;string oldHand=Hand["number"].S;await Run("tick",Turn("botTiming",true),false);if(count!=Hand["eventCount"].I||oldHand!=Hand["number"].S||Session.Null){bool heroTurn=!Session.Null&&!Hand["actor"].Null&&Hand["actor"].I==0;bufferUntil=DateTime.UtcNow.AddMilliseconds(Hero["folded"].B||heroTurn?0:350);Render();}
