 async Task NextHand(){if(endingTable||busy)return;if(Hero["stack"].N<Session["config"]["bb"].N){reviewHold=true;Notice("筹码不足，请补码或结束本场。");return;}HideOverlay();reviewHold=false;settleAt=DateTime.MaxValue;bool straddle=straddleNext;straddleNext=false;int previous=Hand["number"].I;await Run("next",Turn("playerStraddle",straddle));if(!Session.Null&&Hand["number"].I==previous)reviewHold=true;}
 void UpdateClocks(){UpdateAvatarClock();if(clockText!=null&&!Session.Null){DateTime end;if(DateTime.TryParse(Session["expiresAt"].S,out end)){TimeSpan left=end.ToUniversalTime()-DateTime.UtcNow;clockText.Text=left<=TimeSpan.Zero?"本手结束后结算":left.ToString(@"hh\:mm\:ss");}}if(actionClock!=null){if(paused){actionClock.Text="已暂停";return;}if(Hand["status"].S=="complete")actionClock.Text=reviewHold?"复盘中":"下一手 "+Math.Max(0,Math.Ceiling((settleAt-DateTime.UtcNow).TotalSeconds))+"s";else if(Hand["allInShowdown"].B&&Hand["runoutNextAt"].N>DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()){string next=Hand["street"].S=="flop"?"转牌":"河牌";actionClock.Text="ALL IN · "+next+" "+Math.Max(0,Math.Ceiling((Hand["runoutNextAt"].N-DateTimeOffset.UtcNow.ToUnixTimeMilliseconds())/1000))+"s";}else if(!Hand["legal"].Null){int seconds=(int)Math.Ceiling((Hand["actionDeadlineAt"].N-DateTimeOffset.UtcNow.ToUnixTimeMilliseconds())/1000),total=(int)Math.Max(1,Math.Ceiling((Hand["actionDeadlineAt"].N-Hand["actionStartedAt"].N)/1000));string key=Session["id"].S+"/"+Hand["number"].S+"/"+Hand["actionStartedAt"].S;if(key!=heroActionClockKey){heroActionClockKey=key;lastTickSecond=-1;PlayTurnPrompt();}actionClock.Text="行动剩余 "+Math.Max(0,seconds)+"s";if(seconds>0&&seconds<=Math.Ceiling(total/2d)&&seconds!=lastTickSecond){lastTickSecond=seconds;PlayClockTick();}}else actionClock.Text=busy&&state["ai"]["mode"].S=="external"?"AI 正在思考…":"等待牌友行动";}}
