 void LoadPokerFaceAssets(){string custom=Path.Combine(root,"assets","cards","faces"),fallback=Path.Combine(root,"素材","图片","扑克牌");string folder=Directory.Exists(custom)&&Directory.GetFiles(custom).Count(file=>Path.GetExtension(file).Equals(".png",StringComparison.OrdinalIgnoreCase))==52?custom:fallback;if(!Directory.Exists(folder))return;foreach(string file in Directory.GetFiles(folder)){string extension=Path.GetExtension(file).ToLowerInvariant();if(extension==".png"||extension==".jpg"||extension==".jpeg")pokerFaceAssets[Path.GetFileNameWithoutExtension(file)]=file;}}
