 Grid Dialog(string title,out StackPanel content,out StackPanel footer){var g=new Grid();g.RowDefinitions.Add(new RowDefinition{Height=new GridLength(64)});g.RowDefinitions.Add(new RowDefinition());g.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});var header=new Grid{Background=UI.Brush("#10231E")};header.ColumnDefinitions.Add(new ColumnDefinition());header.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(52)});var heading=UI.Text(title,25,UI.Ink,true);heading.VerticalAlignment=VerticalAlignment.Center;header.Children.Add(heading);var close=UI.Button("",HideOverlay,42);close.Content=UI.CloseIcon(18,UI.Ink);close.Padding=new Thickness(0);close.Margin=new Thickness(0,10,0,10);close.Background=UI.Brush("#0A1714");close.BorderBrush=UI.Brush("#42685C");close.ToolTip="关闭";Grid.SetColumn(close,1);header.Children.Add(close);var headerFrame=new Border{Child=header,BorderBrush=UI.Brush("#315349"),BorderThickness=new Thickness(0,0,0,1)};g.Children.Add(headerFrame);content=UI.Stack();content.Margin=new Thickness(8,14,8,14);var scroll=UI.Scroll(content);Grid.SetRow(scroll,1);g.Children.Add(scroll);footer=UI.Stack(true);footer.HorizontalAlignment=HorizontalAlignment.Right;footer.Margin=new Thickness(8,14,0,0);var footerFrame=new Border{Child=footer,BorderBrush=UI.Brush("#29483F"),BorderThickness=new Thickness(0,1,0,0)};Grid.SetRow(footerFrame,2);g.Children.Add(footerFrame);return g;}
