 void ShowGuide(){StackPanel p,f;var d=Dialog("游戏指南",out p,out f);p.Children.Add(UI.Text("无限注德州扑克 · 52 张牌\n\n每人两张底牌，公共牌依次发出 3 / 1 / 1 张。从七张牌中选择最佳五张。\n\n加注金额是本轮累计投入；最小完整加注幅度按规则计算。短筹码全下不一定重新开放加注权。不同投入额拆分主池和边池，多余未跟注金额退回。\n\n牌型：同花顺 → 四条 → 葫芦 → 同花 → 顺子 → 三条 → 两对 → 一对 → 高牌。\n\nF：翻牌前快速弃牌，立即结束你的本手　F11：全屏　Esc：关闭面板\n\n精简复盘可从牌桌的 HANDS 或菜单主动打开；结束本场后，在大厅进入详细回放。完成至少一手并下桌后，可在牌友档案里判断本场对手身份。",17));ShowOverlay(d,850,640);}
